# File: res://scripts/settings_manager.gd
extends Node

const SETTINGS_PATH: String = "user://settings.cfg"
var config := ConfigFile.new()

func set_bus_linear_volume(bus_name: String, linear: float) -> void:
    var idx: int = AudioServer.get_bus_index(bus_name)
    if idx == -1:
        return
    var clamped: float = clampf(linear, 0.0, 1.0)
    AudioServer.set_bus_mute(idx, clamped <= 0.001)
    AudioServer.set_bus_volume_db(idx, linear_to_db(maxf(clamped, 0.001)))
    config.set_value("audio", bus_name, clamped)
    config.save(SETTINGS_PATH)

# Switching Languages Live with TranslationServer & tr():
func set_game_language(locale_code: String) -> void:
    TranslationServer.set_locale(locale_code) # e.g. "en" or "sw"

func refresh_localized_hud(play_btn: Button, draw_btn: Button, staged_count: int) -> void:
    play_btn.text = "%s (%d)" % [tr("UI_PLAY"), staged_count]
    draw_btn.text = tr("UI_DRAW")

# Micro-Benchmarking & Background Threaded Scene Loading:
static func benchmark_callable_ms(task: Callable) -> float:
    var start_usec: int = Time.get_ticks_usec()
    task.call()
    var end_usec: int = Time.get_ticks_usec()
    return float(end_usec - start_usec) / 1000.0

func poll_threaded_load(path: String, bar: ProgressBar) -> PackedScene:
    var progress: Array = []
    var status := ResourceLoader.load_threaded_get_status(path, progress)
    if not progress.is_empty():
        bar.value = float(progress[0]) * 100.0
    if status == ResourceLoader.THREAD_LOAD_LOADED:
        return ResourceLoader.load_threaded_get(path) as PackedScene
    return null

